const result = JSON.parse($input.first().json.text);

if (!Array.isArray(result.folders)) {
  throw new Error('Keine Ordnerliste erhalten');
}

return result.folders.map(folder => ({
  json: {
    name: folder.name,
    description: folder.description
  }
}));

// Gemini 3.5 Flash-Lite, EU, Standardpreise je 1 Mio. Tokens
const prices = { input: 0.33, cachedInput: 0.033, output: 2.75 };

function usageForRound(index) {
  const totals = {
    inputTokens: 0,
    cachedInputTokens: 0,
    outputTokens: 0,
    estimatedCostUSD: 0
  };

  for (const name of [
    'Vertex-Antwort Kategorien',
    'Vertex-Antwort Zuordnung'
  ]) {
    const result = $(name).first(0, index).json;
    const u = result.usage;

    if (result.model !== 'gemini-3.5-flash-lite' ||
        !Number.isFinite(u?.promptTokenCount) ||
        !Number.isFinite(u?.candidatesTokenCount)) {
      throw new Error(`Modell oder Nutzungsdaten prüfen: ${name}`);
    }

    const input = u.promptTokenCount;
    const cached = u.cachedContentTokenCount ?? 0;
    const output = u.candidatesTokenCount + (u.thoughtsTokenCount ?? 0);

    totals.inputTokens += input;
    totals.cachedInputTokens += cached;
    totals.outputTokens += output;
    totals.estimatedCostUSD += (
      (input - cached) * prices.input +
      cached * prices.cachedInput +
      output * prices.output
    ) / 1_000_000;
  }

  return totals;
}

const current = usageForRound($runIndex);
const total = {
  inputTokens: 0,
  cachedInputTokens: 0,
  outputTokens: 0,
  estimatedCostUSD: 0
};

for (let i = 0; i <= $runIndex; i++) {
  const usage = usageForRound(i);
  for (const key of Object.keys(total)) total[key] += usage[key];
}

return [{
  json: {
    processed: $input.all().length,
    round: $runIndex + 1,
    empty: false,
    currentUsage: current,
    totalUsage: total,
    pricingDate: '2026-11-12',
    currency: 'USD'
  }
}];

const response = $input.first().json;

if (response.candidates?.[0]?.finishReason !== 'STOP') {
  throw new Error('Modellantwort unvollständig');
}

return [{
  json: {
    text: response.candidates[0].content.parts
      .filter(part => typeof part.text === 'string' && !part.thought)
      .map(part => part.text)
      .join(''),
    usage: response.usageMetadata,
    model: response.modelVersion,
    responseId: response.responseId
  }
}];

