const existing = new Set(
  $('Daten bündeln').first().json.folders.map(f => f.path)
);

const folders = $input.all().map(item => ({
  ...item.json,
  path: `INBOX.${item.json.name}`
}));

return [{
  json: {
    folders,
    missingFolders: folders.filter(f => !existing.has(f.path))
  }
}];

return [{
  json: {
    folders: $('Ordner Vorschläge')
      .first(0, $runIndex).json.folders,
    emails: $('Daten bündeln')
      .first(0, $runIndex).json.emails
  }
}];

const text = $input.first().json.text
  .trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/, '');

const parsed = JSON.parse(text);
const assignments = Array.isArray(parsed)
  ? parsed
  : parsed.assignments;
const emails = $('Mails abrufen').all(0, $runIndex);
const expected = new Set(emails.map(i => String(i.json.uid)));
const allowed = new Set(
  $('Ordner-Vorschläge')
    .all(0, $runIndex)
    .map(i => `INBOX.${i.json.name}`)
);
const seen = new Set();

if (!Array.isArray(assignments)) {
  throw new Error('Keine Zuordnungen erhalten');
}

for (const a of assignments) {
  const uid = String(a.uid);

  if (!expected.has(uid) || seen.has(uid)) {
    throw new Error(`Unbekannte oder doppelte UID: ${uid}`);
  }
  if (!allowed.has(a.folderPath)) {
    throw new Error(`Unbekannter Ordner: ${a.folderPath}`);
  }
  seen.add(uid);
}

if (seen.size !== expected.size) {
  throw new Error('Nicht alle Mails wurden zugeordnet');
}

return assignments.map(a => ({ json: a }));
